toolArgs.file_text:
@page "/settings"
@rendermode InteractiveServer
@using sv_0fd758ae4d3540648ee3f2429debb351.Models
@using sv_0fd758ae4d3540648ee3f2429debb351.Services
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <h5 class="sidebar-title">Settings</h5>
        <ul class="nav flex-column">
            @foreach (var section in _sections)
            {
                <li class="nav-item">
                    <button class="nav-link @(ActiveSection == section.Key ? "active" : "")"
                            @onclick="() => ActiveSection = section.Key">
                        <span class="section-icon">@section.Value.Icon</span>
                        @section.Value.Label
                    </button>
                </li>
            }
        </ul>
    </nav>

    <div class="settings-content">
        @if (_loading)
        {
            <div class="d-flex justify-content-center py-5">
                <div class="spinner-border text-primary" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        }
        else
        {
            @switch (ActiveSection)
            {
                case "profile":
                    @RenderProfileSection()
                    break;
                case "notifications":
                    @RenderNotificationsSection()
                    break;
                case "security":
                    @RenderSecuritySection()
                    break;
                case "appearance":
                    @RenderAppearanceSection()
                    break;
            }
        }

        @if (_toastVisible)
        {
            <div class="toast-notification @(_toastIsError ? "toast-error" : "toast-success")">
                @_toastMessage
            </div>
        }
    </div>
</div>

@* ───── Profile Section ───── *@
@code {
    private RenderFragment RenderProfileSection() => __builder =>
    {
        <section class="settings-section">
            <h3>Profile</h3>
            <p class="text-muted">Manage your public profile information.</p>
            <hr />

            <div class="avatar-area mb-4">
                <img src="@_editAvatarUrl" alt="Avatar" class="avatar-preview" />
                <div class="mt-2">
                    <label class="form-label fw-semibold">Avatar URL</label>
                    <input type="text" class="form-control" @bind="_editAvatarUrl" />
                </div>
            </div>

            <div class="mb-3">
                <label class="form-label fw-semibold">Display Name</label>
                <input type="text" class="form-control" @bind="_editDisplayName" />
            </div>

            <div class="mb-3">
                <label class="form-label fw-semibold">Email</label>
                <input type="email" class="form-control" @bind="_editEmail" />
            </div>

            <div class="mb-3">
                <label class="form-label fw-semibold">Bio</label>
                <textarea class="form-control" rows="4" @bind="_editBio"></textarea>
            </div>

            <div class="d-flex gap-2">
                <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                <button class="btn btn-outline-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
            </div>
        </section>
    };
}

@* ───── Notifications Section ───── *@
@code {
    private RenderFragment RenderNotificationsSection() => __builder =>
    {
        <section class="settings-section">
            <h3>Notifications</h3>
            <p class="text-muted">Choose how you want to be notified.</p>
            <hr />

            <div class="mb-3">
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" id="emailNotif" @bind="_editEmailNotifications" />
                    <label class="form-check-label" for="emailNotif">Email Notifications</label>
                </div>
            </div>

            <div class="mb-3">
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" id="pushNotif" @bind="_editPushNotifications" />
                    <label class="form-check-label" for="pushNotif">Push Notifications</label>
                </div>
            </div>

            <div class="mb-3">
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" id="weeklyDigest" @bind="_editWeeklyDigest" />
                    <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
                </div>
            </div>

            <h5 class="mt-4">Muted Channels</h5>
            <p class="text-muted small">Check channels you want to mute.</p>

            <div class="channel-list">
                @foreach (var channel in MockSettingsService.AllChannels)
                {
                    var isMuted = _editMutedChannels.Contains(channel);
                    <div class="form-check mb-2">
                        <input class="form-check-input" type="checkbox" id="ch-@channel"
                               checked="@isMuted"
                               @onchange="e => ToggleMutedChannel(channel, (bool)e.Value!)" />
                        <label class="form-check-label" for="ch-@channel">
                            #@channel
                        </label>
                    </div>
                }
            </div>

            <button class="btn btn-primary mt-3" @onclick="SaveNotifications">Save Preferences</button>
        </section>
    };
}

@* ───── Security Section ───── *@
@code {
    private RenderFragment RenderSecuritySection() => __builder =>
    {
        <section class="settings-section">
            <h3>Security</h3>
            <p class="text-muted">Manage your account security settings.</p>
            <hr />

            @* Change Password Panel *@
            <div class="card mb-4">
                <div class="card-header d-flex justify-content-between align-items-center"
                     style="cursor: pointer;" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                    <span class="fw-semibold">Change Password</span>
                    <span>@(_passwordPanelOpen ? "▲" : "▼")</span>
                </div>
                @if (_passwordPanelOpen)
                {
                    <div class="card-body">
                        <div class="mb-3">
                            <label class="form-label">Current Password</label>
                            <input type="password" class="form-control" @bind="_currentPassword" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label">New Password</label>
                            <input type="password" class="form-control" @bind="_newPassword" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Confirm New Password</label>
                            <input type="password" class="form-control" @bind="_confirmPassword" />
                        </div>
                        <button class="btn btn-warning" @onclick="UpdatePassword">Update Password</button>
                    </div>
                }
            </div>

            @* Two-Factor Authentication *@
            <div class="card mb-4">
                <div class="card-body d-flex justify-content-between align-items-center">
                    <div>
                        <h6 class="mb-1">Two-Factor Authentication</h6>
                        <span class="badge @(_securitySettings!.TwoFactorEnabled ? "bg-success" : "bg-secondary")">
                            @(_securitySettings.TwoFactorEnabled ? "Enabled" : "Disabled")
                        </span>
                        @if (_securitySettings.LastPasswordChange.HasValue)
                        {
                            <small class="text-muted d-block mt-1">
                                Last password change: @_securitySettings.LastPasswordChange.Value.ToString("MMM dd, yyyy")
                            </small>
                        }
                    </div>
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" checked="@_securitySettings.TwoFactorEnabled"
                               @onchange="Toggle2FA" />
                    </div>
                </div>
            </div>

            @* Active Sessions *@
            <h5>Active Sessions</h5>
            <div class="table-responsive">
                <table class="table table-hover">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @foreach (var session in _securitySettings.Sessions)
                        {
                            var isCurrentSession = session.Id == _securitySettings.Sessions.FirstOrDefault()?.Id;
                            <tr>
                                <td>@session.Device</td>
                                <td>@session.Location</td>
                                <td>@FormatLastActive(session.LastActive)</td>
                                <td>
                                    @if (isCurrentSession)
                                    {
                                        <span class="badge bg-info">Current</span>
                                    }
                                    else
                                    {
                                        <button class="btn btn-sm btn-outline-danger"
                                                @onclick="() => PromptRevokeSession(session)">
                                            Revoke
                                        </button>
                                    }
                                </td>
                            </tr>
                        }
                    </tbody>
                </table>
            </div>

            @* Revoke Confirmation Dialog *@
            @if (_sessionToRevoke is not null)
            {
                <div class="modal-backdrop show"></div>
                <div class="modal d-block" tabindex="-1">
                    <div class="modal-dialog modal-dialog-centered">
                        <div class="modal-content">
                            <div class="modal-header">
                                <h5 class="modal-title">Revoke Session</h5>
                                <button type="button" class="btn-close" @onclick="CancelRevoke"></button>
                            </div>
                            <div class="modal-body">
                                <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> in <strong>@_sessionToRevoke.Location</strong>?</p>
                                <p class="text-muted small">This will immediately sign out that device.</p>
                            </div>
                            <div class="modal-footer">
                                <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                                <button class="btn btn-danger" @onclick="ConfirmRevoke">Revoke Session</button>
                            </div>
                        </div>
                    </div>
                </div>
            }
        </section>
    };
}

@* ───── Appearance Section ───── *@
@code {
    private RenderFragment RenderAppearanceSection() => __builder =>
    {
        <section class="settings-section">
            <h3>Appearance</h3>
            <p class="text-muted">Customize the look and feel of the application.</p>
            <hr />

            <div class="row">
                <div class="col-md-7">
                    @* Theme *@
                    <h5>Theme</h5>
                    <div class="mb-4">
                        @foreach (var theme in new[] { "Light", "Dark", "System" })
                        {
                            <div class="form-check">
                                <input class="form-check-input" type="radio" name="theme" id="theme-@theme"
                                       value="@theme" checked="@(_editTheme == theme)"
                                       @onchange="() => _editTheme = theme" />
                                <label class="form-check-label" for="theme-@theme">@theme</label>
                            </div>
                        }
                    </div>

                    @* Font Size *@
                    <h5>Font Size</h5>
                    <div class="mb-4">
                        @foreach (var size in new[] { "Small", "Medium", "Large" })
                        {
                            <div class="form-check">
                                <input class="form-check-input" type="radio" name="fontSize" id="fs-@size"
                                       value="@size" checked="@(_editFontSize == size)"
                                       @onchange="() => _editFontSize = size" />
                                <label class="form-check-label" for="fs-@size">@size</label>
                            </div>
                        }
                    </div>

                    @* Language *@
                    <div class="mb-4">
                        <h5>Language</h5>
                        <select class="form-select" style="max-width: 250px;" @bind="_editLanguage">
                            <option>English</option>
                            <option>Spanish</option>
                            <option>French</option>
                            <option>German</option>
                            <option>Japanese</option>
                            <option>Portuguese</option>
                        </select>
                    </div>

                    @* Compact Mode *@
                    <div class="mb-4">
                        <div class="form-check form-switch">
                            <input class="form-check-input" type="checkbox" id="compactMode" @bind="_editCompactMode" />
                            <label class="form-check-label" for="compactMode">Compact Mode</label>
                        </div>
                    </div>

                    <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
                </div>

                @* Live Preview *@
                <div class="col-md-5">
                    <h5>Preview</h5>
                    <div class="live-preview @GetPreviewClasses()">
                        <div class="preview-header">
                            <strong>Settings Dashboard</strong>
                        </div>
                        <div class="preview-body">
                            <p>This is a preview of your selected appearance settings.</p>
                            <div class="preview-card">
                                <span class="preview-label">Notification</span>
                                <span>You have 3 new messages.</span>
                            </div>
                            <button class="preview-btn">Sample Button</button>
                        </div>
                        <div class="preview-footer">
                            <small>Language: @_editLanguage · Font: @_editFontSize · @(_editCompactMode ? "Compact" : "Normal")</small>
                        </div>
                    </div>
                </div>
            </div>
        </section>
    };
}

@* ───── Code-behind ───── *@
@code {
    private record SectionInfo(string Label, string Icon);

    private readonly Dictionary<string, SectionInfo> _sections = new()
    {
        ["profile"] = new("Profile", "👤"),
        ["notifications"] = new("Notifications", "🔔"),
        ["security"] = new("Security", "🔒"),
        ["appearance"] = new("Appearance", "🎨"),
    };

    private string ActiveSection { get; set; } = "profile";
    private bool _loading = true;

    // Toast
    private bool _toastVisible;
    private string _toastMessage = "";
    private bool _toastIsError;

    // Profile state
    private UserProfile? _savedProfile;
    private string _editDisplayName = "";
    private string _editEmail = "";
    private string _editAvatarUrl = "";
    private string _editBio = "";

    // Notification state
    private bool _editEmailNotifications;
    private bool _editPushNotifications;
    private bool _editWeeklyDigest;
    private List<string> _editMutedChannels = [];

    // Security state
    private SecuritySettings? _securitySettings;
    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private ActiveSession? _sessionToRevoke;

    // Appearance state
    private string _editTheme = "Light";
    private string _editFontSize = "Medium";
    private string _editLanguage = "English";
    private bool _editCompactMode;

    protected override async Task OnInitializedAsync()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifTask, securityTask, appearanceTask);

        LoadProfileState(profileTask.Result);
        LoadNotificationState(notifTask.Result);
        _securitySettings = securityTask.Result;
        LoadAppearanceState(appearanceTask.Result);

        _loading = false;
    }

    // ── Profile helpers ──

    private void LoadProfileState(UserProfile profile)
    {
        _savedProfile = profile;
        _editDisplayName = profile.DisplayName;
        _editEmail = profile.Email;
        _editAvatarUrl = profile.AvatarUrl;
        _editBio = profile.Bio;
    }

    private async Task SaveProfile()
    {
        var updated = new UserProfile(_editDisplayName, _editEmail, _editAvatarUrl, _editBio);
        await SettingsService.SaveProfileAsync(updated);
        _savedProfile = updated;
        await ShowToast("Profile saved successfully.");
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile is not null)
            LoadProfileState(_savedProfile);
    }

    // ── Notification helpers ──

    private void LoadNotificationState(NotificationPrefs prefs)
    {
        _editEmailNotifications = prefs.EmailNotifications;
        _editPushNotifications = prefs.PushNotifications;
        _editWeeklyDigest = prefs.WeeklyDigest;
        _editMutedChannels = [.. prefs.MutedChannels];
    }

    private void ToggleMutedChannel(string channel, bool muted)
    {
        if (muted && !_editMutedChannels.Contains(channel))
            _editMutedChannels.Add(channel);
        else if (!muted)
            _editMutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(_editEmailNotifications, _editPushNotifications, _editWeeklyDigest, [.. _editMutedChannels]);
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        await ShowToast("Notification preferences saved.");
    }

    // ── Security helpers ──

    private async Task UpdatePassword()
    {
        if (string.IsNullOrWhiteSpace(_newPassword) || _newPassword != _confirmPassword)
        {
            await ShowToast("Passwords do not match or are empty.", isError: true);
            return;
        }
        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _passwordPanelOpen = false;
        await ShowToast("Password updated successfully.");
    }

    private async Task Toggle2FA(ChangeEventArgs e)
    {
        var enabled = (bool)e.Value!;
        // In a real app, this would trigger a 2FA setup flow
        _securitySettings = _securitySettings! with { TwoFactorEnabled = enabled };
        await ShowToast(enabled ? "Two-factor authentication enabled." : "Two-factor authentication disabled.");
    }

    private void PromptRevokeSession(ActiveSession session)
    {
        _sessionToRevoke = session;
    }

    private void CancelRevoke() => _sessionToRevoke = null;

    private async Task ConfirmRevoke()
    {
        if (_sessionToRevoke is null) return;
        await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        _sessionToRevoke = null;
        await ShowToast("Session revoked.");
    }

    // ── Appearance helpers ──

    private void LoadAppearanceState(AppearanceSettings settings)
    {
        _editTheme = settings.Theme;
        _editFontSize = settings.FontSize;
        _editLanguage = settings.Language;
        _editCompactMode = settings.CompactMode;
    }

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        classes.Add(_editTheme.ToLowerInvariant() switch
        {
            "dark" => "preview-dark",
            "system" => "preview-system",
            _ => "preview-light"
        });
        classes.Add($"preview-font-{_editFontSize.ToLowerInvariant()}");
        if (_editCompactMode) classes.Add("preview-compact");
        return string.Join(" ", classes);
    }

    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(_editTheme, _editFontSize, _editLanguage, _editCompactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        await ShowToast("Appearance settings saved.");
    }

    // ── Toast ──

    private string FormatLastActive(DateTime dt)
    {
        var diff = DateTime.UtcNow - dt;
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }

    private async Task ShowToast(string message, bool isError = false)
    {
        _toastMessage = message;
        _toastIsError = isError;
        _toastVisible = true;
        StateHasChanged();
        await Task.Delay(3000);
        _toastVisible = false;
        StateHasChanged();
    }
}

